1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Atlas Search Results</title>
7	<style>
8	  * { box-sizing: border-box }
9	  body { margin: 0; font-family: system-ui, sans-serif; background: #f5f6f8; color: #20242b }
10	  header { background: #fff; border-bottom: 1px solid #e4e6ea; padding: 16px 32px; font-weight: 700 }
11	  main { max-width: 680px; margin: 36px auto; padding: 0 24px }
12	  .bar { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px }
13	  h1 { font-size: 20px; margin: 0 }
14	  .dd { position: relative; font-size: 14px }
15	  .dd-toggle { display: flex; align-items: center; gap: 8px; padding: 9px 14px; background: #fff; border: 1px solid #c9ced6; border-radius: 7px; cursor: pointer; user-select: none; font: inherit; color: inherit }
16	  .dd-toggle .caret { font-size: 10px; color: #6a7280 }
17	  .dd-list { position: absolute; right: 0; top: calc(100% + 6px); width: 200px; background: #fff; border: 1px solid #c9ced6; border-radius: 8px; box-shadow: 0 8px 20px rgba(24, 30, 40, 0.12); display: none; z-index: 5 }
18	  .dd-list.open { display: block }
19	  .dd-option { padding: 10px 14px; cursor: pointer }
20	  .dd-option:hover { background: #eef1f5 }
21	  .result { background: #fff; border: 1px solid #e4e6ea; border-radius: 8px; padding: 18px 20px; margin-bottom: 12px }
22	  .result h2 { font-size: 16px; margin: 0 0 6px }
23	  .result h2 a { color: #2456c4; text-decoration: none }
24	  .result p { margin: 0; font-size: 14px; color: #4d5663; line-height: 1.55 }
25	</style>
26	<script>
27	  window.__activated = []
28	  document.addEventListener('click', function (e) {
29	    var hit = e.target instanceof Element ? e.target.closest('[data-track]') : null
30	    var name = hit ? hit.getAttribute('data-track') : null
31	    if (name) window.__activated.push(name)
32	  })
33	</script>
34	</head>
35	<body>
36	<header>Atlas</header>
37	<main>
38	  <div class="bar">
39	    <h1>34 results for "harbor"</h1>
40	    <div class="dd">
41	      <button class="dd-toggle" data-track="dd-toggle" id="sort-toggle" aria-haspopup="listbox" aria-expanded="false" aria-controls="sort-list">
42	        <span id="sort-label">Sort: Relevance</span>
43	        <span class="caret">v</span>
44	      </button>
45	      <div class="dd-list" data-dd-list id="sort-list" role="listbox" aria-label="Sort options">
46	        <div class="dd-option" data-track="dd-option-1" data-value="Relevance" role="option">Relevance</div>
47	        <div class="dd-option" data-track="dd-option-2" data-value="Newest first" role="option">Newest first</div>
48	        <div class="dd-option" data-track="dd-option-3" data-value="Most cited" role="option">Most cited</div>
49	      </div>
50	    </div>
51	  </div>
52	  <div class="result">
53	    <h2><a href="#r1" data-track="result-1">Harbor Morning: tidal patterns of the north inlet</a></h2>
54	    <p>Field measurements across three seasons show the inlet flushing cycle is closer to eleven days than the fourteen previously modeled.</p>
55	  </div>
56	  <div class="result">
57	    <h2><a href="#r2" data-track="result-2">Dredging records of the outer harbor, 1954 to 2019</a></h2>
58	    <p>A digitized archive of depth soundings and dredge volumes, cross-referenced with storm events and shipping tonnage.</p>
59	  </div>
60	  <div class="result">
61	    <h2><a href="#r3" data-track="result-3">Breakwater vegetation survey</a></h2>
62	    <p>Species counts along the south breakwater, with photographs, sampling notes and a comparison against the 2011 baseline.</p>
63	  </div>
64	</main>
65	<script>
66	  var toggle = document.getElementById('sort-toggle')
67	  var list = document.getElementById('sort-list')
68	  var label = document.getElementById('sort-label')
69	  var options = document.querySelectorAll('.dd-option')
70	  var selectedIndex = 0
71	
72	  function openDropdown() {
73	    list.classList.add('open')
74	    toggle.setAttribute('aria-expanded', 'true')
75	    if (options[selectedIndex]) {
76	      options[selectedIndex].focus()
77	    }
78	  }
79	
80	  function closeDropdown() {
81	    list.classList.remove('open')
82	    toggle.setAttribute('aria-expanded', 'false')
83	    toggle.focus()
84	  }
85	
86	  function selectOption(index) {
87	    if (index >= 0 && index < options.length) {
88	      selectedIndex = index
89	      label.textContent = 'Sort: ' + options[index].getAttribute('data-value')
90	      closeDropdown()
91	    }
92	  }
93	
94	  toggle.addEventListener('click', function () {
95	    if (list.classList.contains('open')) {
96	      closeDropdown()
97	    } else {
98	      openDropdown()
99	    }
100	  })
101	
102	  toggle.addEventListener('keydown', function (e) {
103	    if (e.key === 'ArrowDown' && list.classList.contains('open')) {
104	      e.preventDefault()
105	      selectedIndex = Math.min(selectedIndex + 1, options.length - 1)
106	      options[selectedIndex].focus()
107	    } else if (e.key === 'ArrowUp' && list.classList.contains('open')) {
108	      e.preventDefault()
109	      selectedIndex = Math.max(selectedIndex - 1, 0)
110	      options[selectedIndex].focus()
111	    }
112	  })
113	
114	  Array.prototype.forEach.call(options, function (option, index) {
115	    option.setAttribute('tabindex', '-1')
116	    option.addEventListener('click', function () {
117	      selectOption(index)
118	    })
119	    option.addEventListener('keydown', function (e) {
120	      if (e.key === 'Enter' || e.key === ' ') {
121	        e.preventDefault()
122	        option.click()
123	      } else if (e.key === 'ArrowDown') {
124	        e.preventDefault()
125	        selectedIndex = Math.min(index + 1, options.length - 1)
126	        options[selectedIndex].focus()
127	      } else if (e.key === 'ArrowUp') {
128	        e.preventDefault()
129	        selectedIndex = Math.max(index - 1, 0)
130	        options[selectedIndex].focus()
131	      } else if (e.key === 'Escape') {
132	        e.preventDefault()
133	        closeDropdown()
134	      }
135	    })
136	  })
137	</script>
138	</body>
